MD4_CTX md;
unsigned char result[16];

strcpy(buf, seed);     /* シードは小文字でなければならない */
strcat(buf, passwd);
MD4Init(&md);
MD4Update(&md, (unsigned char *)buf, strlen(buf));
MD4Final(result, &md);

/* 128ビットの結果を64ビットに折りたたむ */
for (i = 0; i < 8; i++)
        result[i] ^= result[i+8];

MD5_CTX md;
unsigned char result[16];
strcpy(buf, seed);     /* シードは小文字でなければならない */
strcat(buf, passwd);
MD5Init(&md);
MD5Update(&md, (unsigned char *)buf, strlen(buf));
MD5Final(result, &md);

/* 128ビットの結果を64ビットに折りたたむ */
for (i = 0; i < 8; i++)
        result[i] ^= result[i+8];

SHA_INFO sha;
unsigned char result[16];
strcpy(buf, seed);     /* シードは小文字でなければならない */
strcat(buf, passwd);
sha_init(&sha);
sha_update(&sha, (unsigned char *)buf, strlen(buf));
sha_final(&sha);       /* 注：結果バッファーはない */

/* 160ビットの結果を64ビットに折りたたむ */
sha.digest[0] ^= sha.digest[2];
sha.digest[1] ^= sha.digest[3];
sha.digest[0] ^= sha.digest[4];

/*
 * 結果の64ビットをリトルエンディアン方式で結果バッファーにコピーする
 * （MD4Final()とMD5Final()が行う方法と同様）。
 */
for (i = 0, j = 0; j < 8; i++, j += 4)
{
        result[j]   = (unsigned char)(sha.digest[i] & 0xff);
        result[j+1] = (unsigned char)((sha.digest[i] >> 8) & 0xff);
        result[j+2] = (unsigned char)((sha.digest[i] >> 16) & 0xff);
        result[j+3] = (unsigned char)((sha.digest[i] >> 24) & 0xff);
}
